// Test inputs for MTF: generated byte patterns, files from disk, and their BWT.
// Everything here is deterministic, so every machine (Windows, the Mac, the AMD
// laptop) builds exactly the same bytes for the same name.
#pragma once

#include "word_encoding.h"

#include <cstddef>
#include <cstdint>
#include <string>
#include <vector>

// The largest input whose last position still gets a word that fits the 30-bit payload.
// Positions map to consecutive words starting at seenAt(0), so seenAt(n - 1) <= kMaxWord
// gives n <= kMaxWord - seenAt(0) + 1. Derived from seenAt, so it follows any change
// to the encoding.
constexpr size_t kMaxInputBytes = size_t(kMaxWord - seenAt(0)) + 1;
static_assert(seenAt(kMaxInputBytes - 1) == kMaxWord, "the last position's word must be the largest that fits");

struct Input
{
    std::string name;
    std::vector<uint8_t> bytes;
};

// Uniform random bytes. Same seed, same bytes, on every compiler.
std::vector<uint8_t> makeRandom(size_t n, uint64_t seed);

// Random bytes drawn from alphabetSize symbols (1..256), spread evenly over 0..255.
std::vector<uint8_t> makeSmallAlphabet(size_t n, uint32_t alphabetSize, uint64_t seed);

// n copies of one byte.
std::vector<uint8_t> makeConstant(size_t n, uint8_t value);

// 0, 1, ..., 255, 0, 1, ...
std::vector<uint8_t> makeCycle(size_t n);

// Reads a whole file. Prints the reason and returns false on failure or if the
// file is larger than kMaxInputBytes.
bool loadFile(const char* path, std::vector<uint8_t>& out);

// Burrows-Wheeler transform via libsais. Returns the transformed bytes and writes
// the primary index (needed only to invert the BWT later). Exits on failure.
std::vector<uint8_t> bwt(const std::vector<uint8_t>& text, int32_t& primaryIndex);

// "D:\data\enwik8" -> "enwik8"
std::string baseName(const char* path);